// ============================================
// HELPERS
// ============================================

function getInstructionsTranslation(id) {
    if (typeof currentLang === 'undefined' || currentLang === 'ru') return null;
    if (typeof instructionsTranslations === 'undefined') return null;
    return instructionsTranslations.en[id] || null;
}

function getInstructions(ex) {
    if (!ex) return null;
    
    if (typeof currentLang === 'undefined' || currentLang === 'ru') {
        return {
            instructions: ex.instructions_ru,
            steps: ex.instruction_steps_ru
        };
    }
    
    const tr = getInstructionsTranslation(ex.id);
    if (!tr) {
        return {
            instructions: ex.instructions_ru,
            steps: ex.instruction_steps_ru
        };
    }
    
    return {
        instructions: tr.instructions_en || ex.instructions_ru,
        steps: tr.instruction_steps_en || ex.instruction_steps_ru
    };
}

function getInstructionsText(ex) {
    return getInstructions(ex)?.instructions || '';
}

function getInstructionSteps(ex) {
    return getInstructions(ex)?.steps || [];
}